{"tool":"write","path":"tests/test_export.py","content":"import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_rfc4180_minimal_quoting_crlf_and_missing_none(self):
        rows = iter([
            {'a': 'x,y', 'b': 'q"q', 'c': 'l\nr', 'd': None, 'e': 5, 'z': 'ignored'},
        ])
        columns = iter(['a', 'b', 'c', 'd', 'e', 'missing'])
        self.assertEqual(
            export_csv(rows, columns),
            'a,b,c,d,e,missing\r\n'
            '"x,y","q""q","l\nr",,5,\r\n'
        )

    def test_empty_rows_and_empty_columns(self):
        self.assertEqual(export_csv([], ['a']), 'a\r\n')
        self.assertEqual(export_csv([{}, {'x': 1}], []), '\r\n\r\n')
        self.assertEqual(export_csv([], []), '\r\n')

    def test_rejects_duplicate_and_non_string_columns(self):
        with self.assertRaises(ValueError):
            export_csv([], ['a', 'a'])
        with self.assertRaises(ValueError):
            export_csv([], ['a', 1])


if __name__ == '__main__':
    unittest.main()
